/**
 * /ship → /document-release Step 18 dispatch stays wired AND visible.
 *
 * The v1.54.0.0 carve (46c1fae7) moved Step 18 (documentation sync) out of
 * the ship skeleton into sections/pr-body.md. The wiring survived, but on
 * the Claude host the skeleton stopped saying "document-release" anywhere
 * in the workflow body — the dispatch became invisible at the decision
 * points and "the idea of running document-release as part of ship got
 * lost". This tripwire pins both halves so neither can silently regress:
 *
 *  - the carved section keeps the full dispatch contract (imperative,
 *    subagent_type, JSON return keys, non-blocking failure), and
 *  - the Claude skeleton names "the /document-release subagent" at its
 *    three touchpoints (manifest trigger via section-index + STOP pointer,
 *    Step 17 handoff, hoisted doc-sync invariant) while the imperative
 *    itself stays carved.
 *
 * Structural backstop lives in test/helpers/carve-guards.ts (ship entry);
 * this named test documents the regression story. Behavioral proof is the
 * ship-docsync E2E (test/skill-e2e-ship-docsync.test.ts).
 */
import { describe, test, expect } from 'bun:test';
import * as fs from 'fs';
import * as path from 'path';

const ROOT = path.join(import.meta.dir, '..');

const SECTION_SITES = [
  path.join(ROOT, 'ship', 'sections', 'pr-body.md'),
  path.join(ROOT, 'ship', 'sections', 'pr-body.md.tmpl'),
];

// ship/SKILL.md only — NOT the claude golden: test/host-config.test.ts
// already enforces golden == generated byte-for-byte, so substring asserts
// on the golden would be pure duplication. The codex/factory goldens ARE
// asserted below because for them the check is content (the inlined
// section survived generation), which byte-equality alone doesn't prove.
const CLAUDE_SKELETON = path.join(ROOT, 'ship', 'SKILL.md');
const INLINED_GOLDENS = [
  path.join(ROOT, 'test', 'fixtures', 'golden', 'codex-ship-SKILL.md'),
  path.join(ROOT, 'test', 'fixtures', 'golden', 'factory-ship-SKILL.md'),
];

const CARVED_IMPERATIVE = 'Dispatch /document-release as a subagent';

describe('/ship Step 18 dispatches /document-release (carve visibility)', () => {
  test('carved section carries the full dispatch contract', () => {
    for (const file of SECTION_SITES) {
      const content = fs.readFileSync(file, 'utf-8');
      expect(content).toContain(
        '## Step 18: Documentation sync (via subagent, before PR creation)'
      );
      expect(content).toContain(CARVED_IMPERATIVE);
      expect(content).toContain('subagent_type: "general-purpose"');
      // The JSON return contract Step 19 bakes into the PR body.
      expect(content).toContain('"files_updated"');
      expect(content).toContain('"commit_sha"');
      expect(content).toContain('"pushed"');
      expect(content).toContain('"documentation_section"');
      // Deliberate design: docs sync never holds a ship hostage.
      expect(content).toContain('Do not block /ship on subagent failure');
      // These four strings are the ship-docsync E2E's dispatch-matcher markers
      // (test/skill-e2e-ship-docsync.test.ts): the first two are INCLUSION
      // markers (verbatim from the dictated Step 18 subagent prompt); the last
      // two are EXCLUSION markers (section scaffolding that disqualifies a
      // whole-section paste). Rewording any of them in pr-body.md.tmpl silently
      // deadens the paid matcher; update all four in lockstep.
      expect(content).toContain('You are executing the /document-release workflow');
      expect(content).toContain('.claude/skills/gstack/document-release/SKILL.md');
      expect(content).toContain('## Step 19: Create PR/MR');
      expect(content).toContain('Parent processing:');
      // #2733: the dispatch marks the subagent spawned so document-release's
      // AUQ gates auto-choose instead of prose-stopping (which breaks the
      // parent's LAST-line JSON parse). Three layers pinned: the env marker
      // prefix, the behavioral instruction, and the framing sentence.
      expect(content).toContain('GSTACK_SESSION_KIND=spawned');
      expect(content).toContain('auto-choose the RECOMMENDED option');
      expect(content).toContain('as a SPAWNED subagent');
      // Auto-chosen gate decisions ride the JSON contract (console-printed by
      // the parent), never the public PR body.
      expect(content).toContain('"decisions"');
      const docHeading = content.indexOf('\n## Documentation\n');
      expect(docHeading, 'PR-body template must carry the ## Documentation heading').toBeGreaterThan(0);
      // End bound searched FROM docHeading and asserted found — otherwise a
      // removed/reordered '## Test plan' heading degrades this guard to a
      // vacuous empty-slice check instead of failing loudly (#2733 review).
      const docEnd = content.indexOf('\n## Test plan\n', docHeading);
      expect(docEnd, '## Test plan heading must follow ## Documentation').toBeGreaterThan(docHeading);
      const docSection = content.slice(docHeading, docEnd);
      expect(docSection, 'decisions must never leak into the PR-body Documentation embed').not.toContain('decisions');
    }
  });

  test('claude skeleton names the subagent at all three touchpoints', () => {
    const content = fs.readFileSync(CLAUDE_SKELETON, 'utf-8');
    // Manifest trigger — renders into the section-index row AND the STOP
    // pointer, so it must appear at least twice.
    const trigger =
      'dispatching the /document-release subagent to sync docs (Step 18) and then creating or updating the PR/MR (Step 19)';
    expect(content.split(trigger).length - 1).toBeGreaterThanOrEqual(2);
    // Step 17 handoff.
    expect(content).toContain(
      'Step 18 (dispatch the /document-release subagent to sync docs)'
    );
    // Hoisted doc-sync invariant (beside the PR-title invariant).
    expect(content).toContain('**Doc-sync invariant');
    expect(content).toContain('dispatches the /document-release subagent');
    // The STOP-Read pointer still routes to the carved section.
    expect(content).toMatch(
      /> \*\*STOP\.\*\*[^\n]*Read `[^`]*ship\/sections\/pr-body\.md`/
    );
    // Ordering pin: the hoisted invariant must sit ABOVE the pr-body STOP
    // pointer (mustStayInSkeleton asserts presence only — a future edit could
    // drift the paragraph below the STOP with every registry check green).
    const invariantIdx = content.indexOf('**Doc-sync invariant');
    const stopIdx = content.indexOf(
      '> **STOP.** Before dispatching the /document-release subagent'
    );
    expect(invariantIdx).toBeGreaterThan(-1);
    expect(stopIdx).toBeGreaterThan(invariantIdx);
  });

  test('the dispatch imperative stays carved out of the claude skeleton', () => {
    const content = fs.readFileSync(CLAUDE_SKELETON, 'utf-8');
    expect(content).not.toContain(CARVED_IMPERATIVE);
  });

  test('manifest trigger names the subagent', () => {
    const manifest = JSON.parse(
      fs.readFileSync(
        path.join(ROOT, 'ship', 'sections', 'manifest.json'),
        'utf-8'
      )
    );
    const prBody = manifest.sections.find(
      (s: { id: string }) => s.id === 'pr-body'
    );
    expect(prBody).toBeDefined();
    expect(prBody.trigger).toContain('the /document-release subagent');
  });

  test('codex + factory goldens inline Step 18 before Step 19', () => {
    for (const file of INLINED_GOLDENS) {
      const content = fs.readFileSync(file, 'utf-8');
      const step18 = content.indexOf(
        '## Step 18: Documentation sync (via subagent, before PR creation)'
      );
      const step19 = content.indexOf('## Step 19: Create PR/MR');
      expect(step18).toBeGreaterThan(-1);
      expect(step19).toBeGreaterThan(step18);
      expect(content).toContain(CARVED_IMPERATIVE);
    }
  });
});

/**
 * Visual diff between two mockups using GPT-4o vision.
 * Identifies what changed between design iterations or between
 * an approved mockup and the live implementation.
 */

import fs from "fs";
import { requireApiKey } from "./auth";
import { receiptedFetch } from "./receipted-fetch";

export interface DiffResult {
  differences: { area: string; description: string; severity: string }[];
  summary: string;
  matchScore: number; // 0-100, how closely they match
}

/**
 * Compare two images and describe the visual differences.
 */
export async function diffMockups(
  beforePath: string,
  afterPath: string,
): Promise<DiffResult> {
  const apiKey = requireApiKey();
  const beforeData = fs.readFileSync(beforePath).toString("base64");
  const afterData = fs.readFileSync(afterPath).toString("base64");

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 60_000);

  try {
    const response = await receiptedFetch("diff-screenshots-request", "https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o",
        messages: [{
          role: "user",
          content: [
            {
              type: "text",
              text: `Compare these two UI images. The first is the BEFORE (or design intent), the second is the AFTER (or actual implementation). Return valid JSON only:

{
  "differences": [
    {"area": "header", "description": "Font size changed from ~32px to ~24px", "severity": "high"},
    ...
  ],
  "summary": "one sentence overall assessment",
  "matchScore": 85
}

severity: "high" = noticeable to any user, "medium" = visible on close inspection, "low" = minor/pixel-level.
matchScore: 100 = identical, 0 = completely different.
Focus on layout, typography, colors, spacing, and element presence/absence. Ignore rendering differences (anti-aliasing, sub-pixel).`,
            },
            {
              type: "image_url",
              image_url: { url: `data:image/png;base64,${beforeData}` },
            },
            {
              type: "image_url",
              image_url: { url: `data:image/png;base64,${afterData}` },
            },
          ],
        }],
        max_tokens: 600,
        response_format: { type: "json_object" },
      }),
      signal: controller.signal,
    });

    if (!response.ok) {
      const error = await response.text();
      console.error(`Diff API error (${response.status}): ${error.slice(0, 200)}`);
      return { differences: [], summary: "Diff unavailable", matchScore: -1 };
    }

    const data = await response.json() as any;
    const content = data.choices?.[0]?.message?.content?.trim() || "";
    return JSON.parse(content) as DiffResult;
  } finally {
    clearTimeout(timeout);
  }
}

/**
 * Verify a live implementation against an approved design mockup.
 * Combines diff with a pass/fail gate.
 */
export async function verifyAgainstMockup(
  mockupPath: string,
  screenshotPath: string,
): Promise<{ pass: boolean; matchScore: number; diff: DiffResult }> {
  const diff = await diffMockups(mockupPath, screenshotPath);

  // Pass if matchScore >= 70 and no high-severity differences
  const highSeverity = diff.differences.filter(d => d.severity === "high");
  const pass = diff.matchScore >= 70 && highSeverity.length === 0;

  return { pass, matchScore: diff.matchScore, diff };
}

import type { Extension } from "@uiw/react-codemirror";

export type CodeEditorLanguage =
  | "css"
  | "html"
  | "javascript"
  | "json"
  | "markdown"
  | "python"
  | "text";

export function normalizeCodeEditorLanguage(
  language: string | null | undefined,
): CodeEditorLanguage {
  switch (language?.toLowerCase()) {
    case "css":
    case "scss":
    case "sass":
    case "less":
      return "css";
    case "html":
    case "xml":
      return "html";
    case "javascript":
    case "typescript":
    case "jsx":
    case "tsx":
      return "javascript";
    case "json":
    case "jsonc":
    case "json5":
      return "json";
    case "markdown":
    case "mdx":
      return "markdown";
    case "python":
    case "py":
      return "python";
    default:
      return "text";
  }
}

async function loadLanguageExtension(
  language: CodeEditorLanguage,
): Promise<Extension[]> {
  switch (language) {
    case "css":
      return [(await import("@codemirror/lang-css")).css()];
    case "html":
      return [(await import("@codemirror/lang-html")).html()];
    case "javascript":
      return [(await import("@codemirror/lang-javascript")).javascript()];
    case "json":
      return [(await import("@codemirror/lang-json")).json()];
    case "markdown": {
      const markdownModule = await import("@codemirror/lang-markdown");
      return [
        markdownModule.markdown({ base: markdownModule.markdownLanguage }),
      ];
    }
    case "python":
      return [(await import("@codemirror/lang-python")).python()];
    case "text":
      return [];
  }
}

async function loadTheme(theme: "light" | "dark"): Promise<Extension> {
  if (theme === "dark") {
    const { monokaiInit } = await import("@uiw/codemirror-theme-monokai");
    return monokaiInit({
      settings: {
        background: "transparent",
        gutterBackground: "transparent",
        gutterForeground: "#555",
        gutterActiveForeground: "#fff",
        fontSize: "var(--text-sm)",
      },
    });
  }
  const { basicLightInit } = await import("@uiw/codemirror-theme-basic");
  return basicLightInit({
    settings: {
      background: "transparent",
      fontSize: "var(--text-sm)",
    },
  });
}

export async function loadCodeEditorExtensions(
  language: string | null | undefined,
  theme: "light" | "dark",
) {
  const normalizedLanguage = normalizeCodeEditorLanguage(language);
  const [extensions, loadedTheme] = await Promise.all([
    loadLanguageExtension(normalizedLanguage),
    loadTheme(theme),
  ]);
  return { extensions, theme: loadedTheme };
}

"use client";

import CodeMirror from "@uiw/react-codemirror";
import { useTheme } from "next-themes";
import { useEffect, useState } from "react";

import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";

import { loadCodeEditorExtensions } from "./code-editor-extensions";
import { useThread } from "./messages/context";

export function CodeEditor({
  className,
  placeholder,
  value,
  readonly,
  disabled,
  autoFocus,
  onChange,
  onSave,
  settings,
  language,
}: {
  className?: string;
  placeholder?: string;
  value: string;
  readonly?: boolean;
  disabled?: boolean;
  autoFocus?: boolean;
  onChange?: (value: string) => void;
  onSave?: () => void;
  settings?: unknown;
  language?: string;
}) {
  const {
    thread: { isLoading },
  } = useThread();
  const { resolvedTheme } = useTheme();
  const [loaded, setLoaded] = useState<
    Awaited<ReturnType<typeof loadCodeEditorExtensions>> | undefined
  >();

  useEffect(() => {
    let cancelled = false;
    setLoaded(undefined);
    void loadCodeEditorExtensions(
      language,
      resolvedTheme === "dark" ? "dark" : "light",
    ).then((extensions) => {
      if (!cancelled) setLoaded(extensions);
    });
    return () => {
      cancelled = true;
    };
  }, [language, resolvedTheme]);

  return (
    <div
      className={cn(
        "flex cursor-text flex-col overflow-hidden rounded-md",
        className,
      )}
      onKeyDown={(event) => {
        if (
          (event.metaKey || event.ctrlKey) &&
          event.key.toLowerCase() === "s"
        ) {
          event.preventDefault();
          onSave?.();
        }
      }}
    >
      {isLoading || !loaded ? (
        <Textarea
          className={cn(
            "h-full overflow-auto font-mono [&_.cm-editor]:h-full [&_.cm-focused]:outline-none!",
            "resize-none p-4! [&_.cm-line]:px-2! [&_.cm-line]:py-0!",
            "border-none",
          )}
          readOnly
          value={value}
        />
      ) : (
        <CodeMirror
          editable={readonly !== true && disabled !== true}
          readOnly={readonly === true || disabled === true}
          placeholder={placeholder}
          className={cn(
            "h-full overflow-auto font-mono [&_.cm-editor]:h-full [&_.cm-focused]:outline-none!",
            "px-2 py-0! [&_.cm-line]:px-2! [&_.cm-line]:py-0!",
          )}
          theme={loaded.theme}
          extensions={loaded.extensions}
          basicSetup={{
            foldGutter:
              (settings as { foldGutter?: boolean })?.foldGutter ?? false,
            highlightActiveLine: false,
            highlightActiveLineGutter: false,
            lineNumbers:
              (settings as { lineNumbers?: boolean })?.lineNumbers ?? false,
          }}
          autoFocus={autoFocus}
          onChange={onChange}
          value={value}
        />
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Check, Loader2 } from "lucide-react";
import { cn } from "@/lib/cn";

export function CvEditor() {
  const [content, setContent] = useState("");
  const [loaded, setLoaded] = useState(false);
  const [exists, setExists] = useState(true);
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    fetch("/api/cv")
      .then((r) => r.json())
      .then((d) => {
        setContent(d.content ?? "");
        setExists(d.exists ?? false);
      })
      .finally(() => setLoaded(true));
  }, []);

  async function save() {
    setSaving(true);
    try {
      const res = await fetch("/api/cv", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ content }),
      });
      if (res.ok) {
        setDirty(false);
        setExists(true);
        setSaved(true);
        setTimeout(() => setSaved(false), 2000);
      }
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="mx-auto max-w-6xl px-6 py-8">
      <div className="flex items-end justify-between gap-4">
        <div>
          <h1 className="font-display text-2xl tracking-tight text-landing">CV editor</h1>
          <p className="mt-1 text-sm text-muted">
            Edit <code className="text-foreground">cv.md</code> with live preview.
            {!exists && loaded && <span className="ml-1 text-faint">No cv.md yet — start typing to create it.</span>}
          </p>
        </div>
        <button
          type="button"
          onClick={save}
          disabled={saving || !dirty}
          className={cn(
            "inline-flex items-center justify-center gap-2 rounded-full px-5 py-2 text-sm font-medium transition-colors max-sm:min-h-[44px]",
            dirty
              ? "bg-brand text-brand-foreground hover:bg-brand-200"
              : "border border-border bg-surface text-muted",
          )}
        >
          {saving ? <Loader2 className="size-4 animate-spin" /> : saved ? <Check className="size-4" /> : null}
          {saved ? "Saved" : "Save"}
        </button>
      </div>

      {!loaded ? (
        <div className="mt-6 text-sm text-muted">Loading…</div>
      ) : (
        <div className="mt-6 grid gap-4 lg:grid-cols-2">
          <textarea
            value={content}
            onChange={(e) => {
              setContent(e.target.value);
              setDirty(true);
            }}
            spellCheck={false}
            placeholder="# Your Name&#10;&#10;## Summary&#10;..."
            className="min-h-[60vh] w-full resize-none rounded-2xl border border-border bg-surface/50 p-4 font-mono text-sm leading-relaxed outline-none transition-colors placeholder:text-faint focus:border-brand/40"
          />
          <article className="report-prose min-h-[60vh] overflow-auto rounded-2xl border border-border bg-surface/30 p-5">
            {content.trim() ? (
              <ReactMarkdown remarkPlugins={[remarkGfm]}>{content}</ReactMarkdown>
            ) : (
              <p className="text-muted">Preview appears here.</p>
            )}
          </article>
        </div>
      )}
    </div>
  );
}

